"},{"path":"style.css","content":"*{margin:0;padding:0;box-sizing:border-box}
html,body,#app{width:100%;height:100%;overflow:hidden;font-family:'Segoe UI',system-ui,-apple-system,sans-serif;background:#cfcfd6}
#scene{display:block;width:100%;height:100%}
button{cursor:pointer;border:none;background:none;font-family:inherit}

/* left mode buttons */
#modes{position:absolute;top:16px;left:16px;display:flex;flex-direction:column;gap:14px;z-index:10}
.mode{width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(140,142,150,.75);transition:background .15s;box-shadow:0 2px 8px rgba(0,0,0,.18)}
.mode svg{width:22px;height:22px;fill:#fff}
.mode:hover{background:rgba(110,112,120,.85)}
.mode.active{background:#141519}

/* mute */
#mute{position:absolute;top:14px;right:18px;z-index:10;opacity:.85}
#mute svg{width:22px;height:22px;fill:#8b8d95}

/* bottom toolbar */
#toolbar{position:absolute;left:50%;bottom:22px;transform:translateX(-50%);display:flex;align-items:center;gap:6px;padding:10px 16px;background:rgba(18,19,24,.94);border-radius:30px;z-index:10;box-shadow:0 6px 24px rgba(0,0,0,.35)}
.tbtn{width:34px;height:34px;border-radius:9px;display:flex;align-items:center;justify-content:center;color:#c9cbd2;transition:background .12s}
.tbtn svg{width:19px;height:19px;fill:currentColor}
.tbtn:hover{background:rgba(255,255,255,.12)}
.tbtn:disabled{opacity:.4;cursor:default}
.tbtn:disabled:hover{background:none}
.tbtn.danger{color:#e0655f}
.sep{width:1px;height:24px;background:rgba(255,255,255,.16);margin:0 6px}

#swatches{display:flex;align-items:center;gap:7px}
.swatch{width:26px;height:26px;border-radius:50%;border:2px solid transparent;transition:transform .1s}
.swatch:hover{transform:scale(1.12)}
.swatch.active{border-color:#fff;box-shadow:0 0 0 2px rgba(255,255,255,.35)}
.swatch.rainbow{background:conic-gradient(#f44336,#ff9800,#ffeb3b,#4caf50,#2196f3,#9c27b0,#f44336)}

.selbtn{display:flex;align-items:center;gap:4px;height:34px;padding:0 10px;border-radius:9px;background:rgba(255,255,255,.1);color:#e8e9ec;font-size:14px;font-weight:600}
.selbtn svg{width:14px;height:14px;fill:none;stroke:#c9cbd2;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.selbtn:hover{background:rgba(255,255,255,.2)}

/* dimension popup */
#dimPop{position:absolute;z-index:20;background:#fff;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,.25);padding:6px;min-width:120px;max-height:230px;overflow:auto}
#dimPop button{display:block;width:100%;text-align:left;padding:9px 14px;border-radius:7px;font-size:14px;color:#26282e}
#dimPop button:hover{background:#eef0f5}
#dimPop button.cur{background:#e3e7f0;font-weight:600}

/* tooltips */
[data-tip]{position:relative}
[data-tip]:hover::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 10px);left:50%;transform:translateX(-50%);background:#141519;color:#fff;font-size:12px;padding:5px 9px;border-radius:6px;white-space:nowrap;pointer-events:none;z-index:30}
.mode[data-tip]:hover::after{bottom:auto;top:50%;left:calc(100% + 10px);transform:translateY(-50%)}

/* pause */
#pauseBtn{position:absolute;left:50%;bottom:26px;transform:translateX(-50%);z-index:10;color:#fff;opacity:.9}
#pauseBtn svg{width:34px;height:34px;fill:#fff;filter:drop-shadow(0 2px 6px rgba(0,0,0,.4))}

/* clear dialog */
#overlay{position:absolute;inset:0;background:rgba(10,10,14,.62);display:flex;align-items:center;justify-content:center;z-index:40}
#dialog{position:relative;width:430px;background:#fff;border-radius:14px;padding:28px 30px 26px;box-shadow:0 20px 60px rgba(0,0,0,.4)}
#dialog h2{font-size:21px;color:#181a20;margin-bottom:10px}
#dialog p{font-size:14.5px;line-height:1.5;color:#4a4d55;margin-bottom:22px}
.dlgBtns{display:flex;justify-content:flex-end;gap:12px}
#dlgCancel{padding:9px 20px;border-radius:20px;border:1px solid #d4d6dc;color:#26282e;font-size:14px;font-weight:600;background:#fff}
#dlgCancel:hover{background:#f2f3f6}
#dlgClear{padding:9px 22px;border-radius:20px;background:#e5484d;color:#fff;font-size:14px;font-weight:600}
#dlgClear:hover{background:#d13438}
#dlgClose{position:absolute;top:12px;right:14px;font-size:14px;color:#8a8d95}
#dlgClose:hover{color:#333}

.hidden{display:none!important}
body.playing #toolbar,body.playing #modes{visibility:hidden}
"}]}

{"files": [{"path":"main.js","content":"import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ---------- constants ---------- */
const GRID = 16;                 // studs per side
const STUD = 1;                  // stud spacing
const BRICK_H = 1.1;             // brick body height
const STUD_R = 0.30, STUD_H = 0.20;
const HALF = GRID / 2;           // 8

const COLORS = [
  { name: 'Red',        hex: 0xe0322d },
  { name: 'Orange',     hex: 0xf59e42 },
  { name: 'Yellow',     hex: 0xf7d038 },
  { name: 'Green',      hex: 0x37a35b },
  { name: 'Light Blue', hex: 0x45b8f0 },
  { name: 'Blue',       hex: 0x5b6ee1 },
  { name: 'Purple',     hex: 0x9b4dca },
  { name: 'Gray',       hex: 0x6e6e78 },
];

/* ---------- state ---------- */
let mode = 'place';              // place | move | erase
let colorIdx = 0;
let width = 2, depth = 2;
let playing = false;
const bricks = [];               // {mesh, i, j, layer, w, d}
const occ = new Map();           // "i,j,layer" -> brick
const key = (i, j, l) => i + ',' + j + ',' + l;

/* ---------- renderer / scene ---------- */
const canvas = document.getElementById('scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xcfcfd6);
scene.fog = new THREE.Fog(0xcfcfd6, 55, 110);

const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 300);
camera.position.set(2.5, 15.5, 17);

const controls = new OrbitControls(camera, canvas);
controls.target.set(0, 0.8, 0);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 7;
controls.maxDistance = 55;
controls.maxPolarAngle = Math.PI * 0.49;
controls.enabled = false;

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xffffff, 0x9a9aa4, 1.15));
const sun = new THREE.DirectionalLight(0xffffff, 1.9);
sun.position.set(10, 20, 8);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = sun.shadow.camera.bottom = -16;
sun.shadow.camera.right = sun.shadow.camera.top = 16;
sun.shadow.camera.far = 60;
sun.shadow.bias = -0.0004;
scene.add(sun);

/* ---------- marble ground ---------- */
function marbleTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const g = c.getContext('2d');
  g.fillStyle = '#cdccd4';
  g.fillRect(0, 0, 512, 512);
  for (let n = 0; n < 26; n++) {
    g.strokeStyle = `rgba(120,118,130,${0.05 + Math.random() * 0.07})`;
    g.lineWidth = 0.6 + Math.random() * 1.4;
    g.beginPath();
    let x = Math.random() * 512, y = Math.random() * 512;
    g.moveTo(x, y);
    for (let s = 0; s < 5; s++) {
      x += (Math.random() - 0.5) * 260; y += (Math.random() - 0.5) * 260;
      g.quadraticCurveTo(x + (Math.random() - .5) * 80, y + (Math.random() - .5) * 80, x, y);
    }
    g.stroke();
  }
  for (let n = 0; n < 900; n++) {
    g.fillStyle = `rgba(110,108,120,${Math.random() * 0.05})`;
    g.fillRect(Math.random() * 512, Math.random() * 512, 1.5, 1.5);
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(4, 4);
  return t;
}
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(400, 400),
  new THREE.MeshStandardMaterial({ map: marbleTexture(), roughness: 0.95 })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.45;
ground.receiveShadow = true;
scene.add(ground);

/* ---------- baseplate ---------- */
const plateGroup = new THREE.Group();
scene.add(plateGroup);
const plateMat = new THREE.MeshStandardMaterial({ color: 0xd8d9e2, roughness: 0.55 });
const plate = new THREE.Mesh(new THREE.BoxGeometry(GRID, 0.4, GRID), plateMat);
plate.position.y = -0.2;
plate.receiveShadow = true;
plateGroup.add(plate);

{
  const studGeo = new THREE.CylinderGeometry(0.28, 0.28, 0.16, 18);
  const inst = new THREE.InstancedMesh(studGeo, plateMat, GRID * GRID);
  const m = new THREE.Matrix4();
  let k = 0;
  for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
    m.setPosition(i - HALF + 0.5, 0.08, j - HALF + 0.5);
    inst.setMatrixAt(k++, m);
  }
  inst.receiveShadow = true;
  plateGroup.add(inst);
}
// invisible top plane for raycast
const plateTop = new THREE.Mesh(
  new THREE.PlaneGeometry(GRID, GRID),
  new THREE.MeshBasicMaterial({ visible: false })
);
plateTop.rotation.x = -Math.PI / 2;
plateTop.userData.isPlate = true;
scene.add(plateTop);

/* ---------- brick factory ---------- */
const matCache = new Map();
function brickMat(hex) {
  if (!matCache.has(hex))
    matCache.set(hex, new THREE.MeshStandardMaterial({ color: hex, roughness: 0.32, metalness: 0.02 }));
  return matCache.get(hex);
}

function buildBrickMesh(w, d, mat) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.BoxGeometry(w - 0.06, BRICK_H, d - 0.06), mat);
  body.position.y = BRICK_H / 2;
  g.add(body);
  const studGeo = new THREE.CylinderGeometry(STUD_R, STUD_R, STUD_H, 20);
  for (let a = 0; a < w; a++) for (let b = 0; b < d; b++) {
    const s = new THREE.Mesh(studGeo, mat);
    s.position.set(a - (w - 1) / 2, BRICK_H + STUD_H / 2, b - (d - 1) / 2);
    g.add(s);
  }
  g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  return g;
}

const cellCenter = (i, j) => ({ x: i - HALF + 0.5, z: j - HALF + 0.5 });

function canPlace(i, j, layer, w, d) {
  if (i < 0 || j < 0 || i + w > GRID || j + d > GRID || layer > 24) return false;
  for (let a = i; a < i + w; a++) for (let b = j; b < j + d; b++)
    if (occ.has(key(a, b, layer))) return false;
  return true;
}

function addBrick(i, j, layer, w, d, hex) {
  const mesh = buildBrickMesh(w, d, brickMat(hex));
  const c = cellCenter(i + (w - 1) / 2 - (w - 1) / 2, 0); // placeholder
  const x = i + (w - 1) / 2 - HALF + 0.5;
  const z = j + (d - 1) / 2 - HALF + 0.5;
  mesh.position.set(x, layer * BRICK_H, z);
  const brick = { mesh, i, j, layer, w, d, hex };
  mesh.userData.brick = brick;
  mesh.traverse(o => o.userData.brick = brick);
  scene.add(mesh);
  bricks.push(brick);
  for (let a = i; a < i + w; a++) for (let b = j; b < j + d; b++) occ.set(key(a, b, layer), brick);
  return brick;
}

function removeBrick(brick) {
  scene.remove(brick.mesh);
  const idx = bricks.indexOf(brick);
  if (idx >= 0) bricks.splice(idx, 1);
  for (let a = brick.i; a < brick.i + brick.w; a++)
    for (let b = brick.j; b < brick.j + brick.d; b++)
      occ.delete(key(a, b, brick.layer));
}

function clearAll() { [...bricks].forEach(removeBrick); }

/* ---------- ghost preview ---------- */
const ghostMat = new THREE.MeshStandardMaterial({
  color: 0xffe27a, transparent: true, opacity: 0.55, roughness: 0.4, depthWrite: false
});
let ghost = null;
let ghostSpot = null; // {i,j,layer}

function refreshGhostMesh() {
  if (ghost) scene.remove(ghost);
  ghost = buildBrickMesh(width, depth, ghostMat);
  ghost.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
  ghost.visible = false;
  scene.add(ghost);
  ghostSpot = null;
}
refreshGhostMesh();

/* ---------- raycasting ---------- */
const ray = new THREE.Raycaster();
const mouse = new THREE.Vector2();
let hoveredErase = null;

function setRayFromEvent(e) {
  const r = canvas.getBoundingClientRect();
  mouse.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  mouse.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  ray.setFromCamera(mouse, camera);
}

function updateGhost(e) {
  if (mode !== 'place' || playing) { ghost.visible = false; ghostSpot = null; return; }
  setRayFromEvent(e);
  const targets = [plateTop, ...bricks.map(b => b.mesh)];
  const hits = ray.intersectObjects(targets, true);
  let spot = null;
  for (const h of hits) {
    const b = h.object.userData.brick;
    const p = h.point, n = h.face ? h.face.normal.clone().transformDirection(h.object.matrixWorld) : new THREE.Vector3(0, 1, 0);
    if (!b) { // plate top
      const i = Math.floor(p.x + HALF), j = Math.floor(p.z + HALF);
      spot = { i, j, layer: 0 };
      break;
    }
    if (n.y > 0.5) { // top face -> stack
      const i = Math.floor(p.x + HALF), j = Math.floor(p.z + HALF);
      spot = { i, j, layer: b.layer + 1 };
      break;
    }
    // side face -> adjacent at same layer
    const i = Math.floor(p.x + n.x * 0.5 + HALF), j = Math.floor(p.z + n.z * 0.5 + HALF);
    spot = { i, j, layer: b.layer };
    break;
  }
  if (spot && canPlace(spot.i, spot.j, spot.layer, width, depth)) {
    ghostSpot = spot;
    ghost.position.set(
      spot.i + (width - 1) / 2 - HALF + 0.5,
      spot.layer * BRICK_H,
      spot.j + (depth - 1) / 2 - HALF + 0.5
    );
    ghost.visible = true;
  } else {
    ghost.visible = false;
    ghostSpot = null;
  }
}

function updateEraseHover(e) {
  if (hoveredErase) {
    hoveredErase.mesh.traverse(o => { if (o.isMesh) o.material.emissive?.setHex(0); });
    hoveredErase = null;
  }
  if (mode !== 'erase' || playing) return;
  setRayFromEvent(e);
  const hits = ray.intersectObjects(bricks.map(b => b.mesh), true);
  if (hits.length) {
    const b = hits[0].object.userData.brick;
    hoveredErase = b;
    b.mesh.traverse(o => { if (o.isMesh && o.material.emissive) o.material.emissive.setHex(0x555555); });
    canvas.style.cursor = 'pointer';
  } else canvas.style.cursor = '';
}

/* ---------- pointer events ---------- */
canvas.addEventListener('pointermove', e => {
  if (mode === 'place') updateGhost(e);
  else if (mode === 'erase') updateEraseHover(e);
});
canvas.addEventListener('pointerdown', e => {
  if (e.button !== 0 || playing) return;
  if (mode === 'place') {
    updateGhost(e);
    if (ghostSpot && ghost.visible) {
      addBrick(ghostSpot.i, ghostSpot.j, ghostSpot.layer, width, depth, COLORS[colorIdx].hex);
      updateGhost(e);
    }
  } else if (mode === 'erase') {
    updateEraseHover(e);
    if (hoveredErase) {
      const b = hoveredErase;
      b.mesh.traverse(o => { if (o.isMesh) o.material.emissive?.setHex(0); });
      hoveredErase = null;
      removeBrick(b);
    }
  }
});
canvas.addEventListener('pointerleave', () => { ghost.visible = false; ghostSpot = null; });

/* ---------- modes ---------- */
const modeBtns = { place: document.getElementById('mPlace'), move: document.getElementById('mMove'), erase: document.getElementById('mErase') };
function setMode(m) {
  mode = m;
  for (const k in modeBtns) modeBtns[k].classList.toggle('active', k === m);
  controls.enabled = (m === 'move') || playing;
  if (m !== 'place') { ghost.visible = false; ghostSpot = null; }
  if (m !== 'erase' && hoveredErase) {
    hoveredErase.mesh.traverse(o => { if (o.isMesh) o.material.emissive?.setHex(0); });
    hoveredErase = null;
  }
  canvas.style.cursor = '';
}
modeBtns.place.onclick = () => setMode('place');
modeBtns.move.onclick = () => setMode('move');
modeBtns.erase.onclick = () => setMode('erase');

/* ---------- swatches ---------- */
const swWrap = document.getElementById('swatches');
COLORS.forEach((c, i) => {
  const b = document.createElement('button');
  b.className = 'swatch' + (i === colorIdx ? ' active' : '');
  b.style.background = '#' + c.hex.toString(16).padStart(6, '0');
  b.dataset.tip = `${c.name} (${i + 1})`;
  b.onclick = () => setColor(i);
  swWrap.appendChild(b);
});
function setColor(i) {
  colorIdx = i;
