  refreshGhostMesh();
}

/* ---------- play / pause ---------- */
const pauseBtn = document.getElementById('pauseBtn');
document.getElementById('play').onclick = () => {
  playing = true;
  document.body.classList.add('playing');
  pauseBtn.classList.remove('hidden');
